    "batch-community-final-436-q011": {"answers":["B"],"confidence":"supported","basis":"concept","explanation":"Colorectal cancer is an important preventable and screen-detectable burden among Saudi men. The lecture lists it as the most common male cancer in Saudi Arabia. \"Most common preventable cancer\" is imprecise without a year and a definition of preventability.","references":[{"title":"IARC · GLOBOCAN 2024 Saudi Arabia cancer estimates","url":"https://gco.iarc.who.int/media/globocan/factsheets/populations/682-saudi-arabia-fact-sheet.pdf"}],"evidence":{"title":"Cancer Prevention and Control","cohortLabel":"MED444","url":"https://drive.google.com/file/d/1UZQUxurClyPg7s7QxQCnc8PUNvhZT5pi/view#page=3","unit":"page","page":3,"quote":"While colorectal in men (in Saudi).","relation":"background","image":"lecture-media/community-batch-review/1UZQUxurClyPg7s7QxQCnc8PUNvhZT5pi-003.jpg","sourceSha256":"1c600132af7e01a07098238dcf52c46ad670d901cdf4f3e37a9167c4697a4ab3","imageSha256":"8f1f487bf9814a7e7690457b0fc6f5d042b91fc4a3741ac33e4bb0783cebffee"}},
